WITH filtered AS (SELECT id, customer_id, order_date, status, channel, amount, discount, shipping_fee, CEIL(shipping_fee) AS shipping_fee_whole, DATEDIFF(CURRENT_DATE(), order_date) AS days_since_order_date FROM orders WHERE customer_id IS NOT NULL AND status = 'SHIPPED') SELECT s.*, latest.method FROM filtered s JOIN LATERAL (SELECT c.method FROM payments c WHERE c.order_id = s.id ORDER BY c.paid_at DESC, c.id DESC LIMIT 1) latest ON TRUE
